/*
 Problem: 1464. Maximum Product of Two Elements in an Array
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 13.5 MB (35.08%)
 Tags: Array, Sorting, Heap (Priority Queue)
*/
class Solution {
public:
    int maxProduct(vector<int>& nums) {
        int max1 = 0, max2 = 0;

        for (const auto& d : nums) {
            if (d >= max1) {
                max2 = max1;
                max1 = d;
            } else if (d > max2) {
                max2 = d;
            }
        }

        return (max1 - 1) * (max2 - 1);
    }
};
